void ag_ui_rotate_180_rgb565(uint16_t *pixels, uint16_t width,
                             uint16_t height)
{
  size_t left;
  size_t right;

  if (pixels == NULL || width == 0 || height == 0)
    {
      return;
    }

  left = 0;
  right = (size_t)width * height - 1;
  while (left < right)
    {
      uint16_t value = pixels[left];
      pixels[left++] = pixels[right];
      pixels[right--] = value;
    }
}

