int dsps_dotprod_f32(const float *input_a, const float *input_b,
                     float *output, int length)
{
  float sum = 0.0f;
  for (int i = 0; i < length; i++)
    {
      sum += input_a[i] * input_b[i];
    }

  *output = sum;
  return 0;
}

